/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/vendor/00308670.c, FUN_L12_00308708. */
void start_blarg_commander_knockback(void *unused, struct Moby *m) {
    LobbedVars *d = (LobbedVars *)m->pvars;
    float dir[4];
    float ang;
    float t1, t2;
    float a;
    float g;

    if (random_integer_below(3) == 0) {
        Moby_PlaySound(1, 0x20, m);
    }
    d->unk48 = 0.7f;
    d->timer = truncate_float_to_s32(716.8f);
    d->unk6C = 0.0f;
    m->update_dist = 0xFF;
    m->flags &= ~6;
    ang = FastAddRots(m->rot.z, 3.1415927f);
    dir[0] = FastCos(ang);
    dir[1] = FastSin(ang);
    dir[2] = 1.0f;
    dir[3] = 5627.925f;
    g = g_frame_time_sq;
    d->rise = g * 40.0f;
    d->fall = g * 100.0f;
    t1 = vec_length(d->rise * 4.0f);
    t2 = vec_length(g_frame_time_sq * 40.0f * 4.0f);
    a = g_frame_time_sq * 40.0f;
    d->launch_speed = 3.0f / ((t1 + t1) / a) + g_frame_time_sq * 100.0f * 0.5f * ((t2 + t2) / a);
    d->unk3C = vec_length(a * 4.0f);
    d->unk5D = 0;
    d->unk44 = 1;
    HeadingFromVector(dir, &ang, &d->launch_speed, &d->unk3C);
    InitKnockback(ang, m, &d->arc, 1, 5, 2);
    d->unk6C = g_frame_time + g_frame_time;
    d->unk70 = -1.0f;
    d->unk74 = -1.0f;
    m->flags &= ~0x1000;
    MobyBlendAnimation(m, 1, 0, 0);
}
